import{_ as e,o,c as i,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Indicar audiência futura na capa","description":"","frontmatter":{"title":"Indicar audiência futura na capa","id":"eproc-indicador-audiencia-futura","plataforma":"eproc","grupo":"Eventos","plano":"free","desde":"1.7.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-indicador-audiencia-futura.md","filePath":"funcionalidades/eproc-indicador-audiencia-futura.md"}'),t={name:"funcionalidades/eproc-indicador-audiencia-futura.md"};function n(d,a,s,c,l,u){return o(),i("div",null,a[0]||(a[0]=[r('<h1 id="indicar-audiencia-futura-na-capa" tabindex="-1">Indicar audiência futura na capa <a class="header-anchor" href="#indicar-audiencia-futura-na-capa" aria-label="Permalink to &quot;Indicar audiência futura na capa&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Quando o processo tem audiência designada com data futura, este recurso mostra na capa uma linha por audiência, com o evento, o local e a data, e um link para o evento. Também avisa, em tom de alerta, sobre audiência com data passada sem registro de realização.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo, na capa, logo acima da linha &quot;Localizador(es)&quot;.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra um processo com audiência designada.</li><li>Na capa aparece uma linha como &quot;Evento 12: Audiência de conciliação designada - Local ... - 20/11/2026 14:00&quot;.</li><li>Clique em &quot;Evento 12&quot; para ir até o evento na tabela. Ele fica destacado por alguns instantes, e o botão Voltar do navegador retorna ao ponto anterior.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Avisar também sobre audiência com data passada sem registro de realização</td><td>ligada</td><td>Mostra em tom de alerta as audiências passadas sem evento posterior de realização, cancelamento ou redesignação.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Os dados vêm só da tabela de eventos já carregada. Se a audiência estiver numa página de eventos ainda não carregada, ela não aparece.</li><li>Se o evento já está à vista, o link só destaca a linha, sem rolar a página.</li><li>Audiências de eventos migrados do PJe sem registro de realização não podem ser lançadas nem canceladas no eproc. Na linha delas há um botão (sino riscado) para não sinalizá-las mais naquele processo. A escolha vale só neste computador.</li></ul>',11)]))}const h=e(t,[["render",n]]);export{m as __pageData,h as default};
